Object.assign(window.TEM8_DICTIONARY, {"glory":{"media":{"uk":"media/uk/glory__gb_1.mp3","us":"media/us/glory__us_1.mp3"},"oxford":{"phon":"ˈɡlɔːri","pos":"noun","senses":[{"en":"great success that brings somebody praise and honour and makes them famous","cn":"荣誉；光荣；桂冠","g":"[uncountable]","ex":{"en":"Olympic glory in the 100 metres","cn":"奥林匹克 100 米赛跑的桂冠"}},{"en":"praise and worship of God","cn":"（对上帝的）赞颂，赞美，崇拜","g":"[uncountable]","ex":{"en":"‘Glory to God in the highest’","cn":"“荣耀归于至高无上的上帝”"}},{"en":"great beauty","cn":"壮丽；辉煌；灿烂","g":"[uncountable]","ex":{"en":"The city was spread out beneath us in all its glory.","cn":"这座城市绚丽多彩地展现在我们下方。"}},{"en":"something that is beautiful, impressive, or deserves praise","cn":"优美之物；骄人之处","g":"[countable]","ex":{"en":"The temple is one of the glories of ancient Greece.","cn":"这座神殿是古希腊的一大骄傲。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"光荣；荣耀","en":"Glory is the fame and admiration that you gain by doing something impressive.","ex":{"en":"Walsham had his moment of glory when he won a 20km race.","cn":"沃尔沙姆夺得20公里比赛冠军的那一刻无比荣耀。"}},{"pos":"N-PLURAL 复数名词","cn":"辉煌时刻；巅峰","en":"A person's glories are the occasions when they have done something people greatly admire which makes them famous.","ex":{"en":"The album sees them reliving past glories but not really breaking any new ground.","cn":"这张专辑使他们重温了昔日的辉煌，但实际上没有任何新的突破。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"壮丽；壮观","en":"The glory of something is its great beauty or impressive nature.","ex":{"en":"The glory of the idea blossomed in his mind.","cn":"在他的脑海中这一想法变得越来越宏大。"}},{"pos":"N-COUNT 可数名词","cn":"引以为荣的事物","en":"The glories of a culture or place are the things that people admire most about it.","ex":{"en":"...a tour of Florence, to enjoy the artistic glories of the Italian Renaissance","cn":"领略意大利文艺复兴时期伟大艺术成就的佛罗伦萨之旅"}},{"pos":"VERB 动词","cn":"因…而欣喜；为…而喜悦","en":"If you glory in a situation or activity, you enjoy it very much.","ex":{"en":"The workers were glorying in their new-found freedom","cn":"工人们因才获得的自由而无比喜悦。"}},{"pos":"PHRASE 短语","cn":"一举成名","en":"If you go out in a blaze of glory, you do something very dramatic at the end of your career or your life which makes you famous.","ex":{"en":"I am never going back to prison. I am going to make national news headlines and go out in a blaze of glory.","cn":"我将永远告别监狱，我会成为全国报纸的头条新闻，从此扬名天下。"}}]},"examples":[{"en":"The city was spread out beneath us in all its glory.","cn":"这座城市绚丽多彩地展现在我们下方。"},{"en":"Olympic glory in the 100 metres","cn":"奥林匹克 100 米赛跑的桂冠"}]},"glad":{"media":{"uk":"media/uk/glad__gb_1.mp3","us":"media/us/glad__us_1.mp3"},"oxford":{"phon":"ɡlæd","pos":"adjective","senses":[{"en":"pleased; happy","cn":"高兴；愉快","g":"[not before noun]","ex":{"en":"‘I passed the test!’ ‘I’m so glad.’","cn":"“我考试通过了！”“我太高兴了。”"}},{"en":"grateful for something","cn":"感激；感谢","ex":{"en":"She was very glad of her warm coat in the biting wind.","cn":"在刺骨的寒风中她有温暖的大衣真是谢天谢地。"}},{"en":"very willing to do something","cn":"乐意；情愿；愿意","ex":{"en":"I'd be glad to lend you the money.","cn":"我很乐意借给你钱。"}},{"en":"bringing joy; full of joy","cn":"令人愉快的；使人高兴的；充满欢乐的","g":"[only before noun]","lab":"old-fashioned","ex":{"en":"glad tidings","cn":"喜讯"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"高兴的；愉快的","en":"If you are glad about something, you are happy and pleased about it.","ex":{"en":"I'm glad I relented in the end","cn":"我很高兴自己的态度最终缓和了下来。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"乐意的；非常愿意的","en":"If you say that you will be glad to do something, usually for someone else, you mean that you are willing and eager to do it.","ex":{"en":"I'll be glad to show you everything","cn":"我将很乐意向你们展示一切。"}},{"pos":"PHRASE 短语","cn":"好消息","en":"Glad tidings means good news.","ex":{"en":"...the bringer of glad tidings.","cn":"报喜讯的人"}}]},"examples":[{"en":"‘He doesn't need the pills any more.’ ‘I'm glad about that.’ “","cn":"他不再需要服那些药片了。” “这真让我高兴。”"},{"en":"She was very glad of her warm coat in the biting wind.","cn":"在刺骨的寒风中她有暖融融的大衣真是谢天谢地。"}]},"globally":{"oxford":{"phon":"ˈɡləʊbəli","pos":"adverb","senses":[{"en":"in a way that covers or affects the whole world","cn":"全球的；全世界的","ex":{"en":"We need to start thinking globally.","cn":"我们需要开始从全球视角考虑问题。"}},{"en":"in a way that considers or includes all parts of something","cn":"整体的；全面的；总括的","ex":{"en":"It is important to approach the problem globally.","cn":"从全球范围内解决这个问题非常重要。"}},{"en":"in a way that operates or applies through the whole of a file, program, etc.","cn":"全局的：以在整个文件，程序等中运行或应用的方式","lab":"computing","ex":{"en":"The processing can be applied globally to all digital output signals.","cn":"该处理可以全局应用于所有数字输出信号。"}}]},"media":{"uk":"media/uk/globally__gb_1.mp3","us":"media/us/globally__us_1.mp3"},"examples":[{"en":"We need to start thinking globally.","cn":"我们需着手全面考虑。"},{"en":"We are taking a global view of our business.","cn":""}]},"gleaming":{"media":{"uk":"media/uk/gleaming__gb_1.mp3","us":"media/us/gleaming__us_1.mp3"},"oxford":{"phon":"ˈɡliːmɪŋ","pos":"adjective","senses":[{"en":"shining brightly because of being very clean","cn":"闪光的；明亮的","ex":{"en":"gleaming white teeth","cn":"皓齿"}}]},"examples":[{"en":"gleaming white teeth","cn":"皓齿"},{"en":"His teeth gleamed under his moustache.","cn":""}]},"glyph":{"oxford":{"phon":"ɡlɪf","pos":"noun","senses":[{"en":"a symbol or picture that represents a word, especially one from an ancient writing system","cn":"石雕符号；象形文字","ex":{"en":"how to write the Mayan glyph for cacao","cn":"如何书写可可的玛雅字形"}},{"en":"a small symbol","cn":"图元；字形","lab":"computing","ex":{"en":"This command will call up a table with all available glyphs in that font.","cn":"此命令将调用一个表格，其中包含该字体的所有可用字形。"}}]},"media":{"uk":"media/uk/glyph__gb_1.mp3","us":"media/us/glyph__us_1.mp3"}},"glassy":{"media":{"uk":"media/uk/glassy__gb_1.mp3","us":"media/us/glassy__us_1.mp3"},"oxford":{"phon":"ˈɡlɑːsi","pos":"adjective","senses":[{"en":"like glass; smooth and shiny","cn":"像玻璃一样的；光滑透亮的","ex":{"en":"a glassy lake","cn":"平静清澈的湖水"}},{"en":"showing no feeling or emotion","cn":"无表情的；木然的；呆滞的","ex":{"en":"glassy eyes","cn":"目光呆滞的眼睛"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"像玻璃一样的；光滑的；光亮透明的","en":"If you describe something as glassy, you mean that it is very smooth and shiny, like glass.","ex":{"en":"The water was glassy.","cn":"水面清澈明亮。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（眼神或表情）呆滞的，无表情的","en":"If you describe someone's eyes or expression as glassy, you mean that they are showing no feeling, emotion, or awareness.","ex":{"en":"He was very still, his eyes glassy","cn":"他纹丝不动，目光呆滞。"}}]},"examples":[{"en":"He looked flushed and glassy-eyed.","cn":"他显得满脸通红，目光呆滞。"},{"en":"a glassy look/stare","cn":"呆滞的神色/盯视"}]},"glove":{"oxford":{"phon":"ɡlʌv","pos":"noun","senses":[{"en":"a piece of clothing for the hand, made of wool, leather, etc. with separate parts for each finger and the thumb","cn":"（分手指的）手套","ex":{"en":"a pair of gloves","cn":"一副手套"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（分手指的）手套","en":"Gloves are pieces of clothing which cover your hands and wrists and have individual sections for each finger. You wear gloves to keep your hands warm or dry or to protect them.","ex":{"en":"He stuck his gloves in his pocket.","cn":"他把手套塞进口袋里。"}},{"pos":"PHRASE 短语","cn":"正合适；完全相配","en":"If you say that something fits like a glove, you are emphasizing that it fits exactly."},{"pos":"See also:","cn":"","en":"hand in glove→see: ;"}]},"media":{"img":["media/pic/gloves_accessories_comp.jpg","media/thumb/glove.jpg"],"uk":"media/uk/glove__gb_1.mp3","us":"media/us/glove__us_1.mp3"},"examples":[{"en":"gardening gloves","cn":"园艺用手套"},{"en":"a pair of gloves","cn":"一副手套"}]},"gloves":{"oxford":{"phon":"ɡlʌv","pos":"noun","senses":[{"en":"a covering for the hand, made of wool, leather, etc. with separate parts for each finger and the thumb （","cn":"分手指的）手套"},{"en":"used to say that sb is ready for a fight or an argument","cn":"准备动手打架；做好战斗（或辩论）准备"}]}},"gleefully":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling happy because something good has happened or is going to happen","cn":""},{"en":"happy and satisfied that something has happened, especially something that has happened to someone else or something good they have done","cn":""}]},"media":{"uk":"media/uk/gleefully__gb_1.mp3","us":"media/us/gleefully__us_1.mp3"},"oxford":{"phon":"ˈɡliːfəli","pos":"adverb","senses":[{"en":"in a happy way because of something good you have done or something bad that has happened to somebody else","cn":"欢喜的；高兴的；幸灾乐祸的","ex":{"en":"He gleefully told me about all the different diseases that I could catch.","cn":"他兴高采烈地告诉我我可能感染的所有不同疾病。"}}]}},"glowing":{"media":{"uk":"media/uk/glowing__gb_1.mp3","us":"media/us/glowing__us_1.mp3"},"oxford":{"phon":"ˈɡləʊɪŋ","pos":"adjective","senses":[{"en":"giving enthusiastic praise","cn":"热烈赞扬的；热情洋溢的","ex":{"en":"a glowing account/report/review","cn":"热情洋溢的叙述／报道／评论"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热烈赞扬的；热情洋溢的","en":"A glowing description or opinion about someone or something praises them highly or supports them strongly.","ex":{"en":"The media has been speaking in glowing terms of the relationship between the two countries","cn":"媒体一直盛赞两国关系。"}}]},"examples":[{"en":"He spoke of her performance in the film in glowing terms (= praising her highly).","cn":"他热烈赞扬了她在影片中的表演。"},{"en":"a glowing account/report/review","cn":"热情洋溢的叙述/报道/评论"}]},"glancing":{"media":{"uk":"media/uk/glancing__gb_1.mp3","us":"media/us/glancing__us_1.mp3"},"oxford":{"phon":"ˈɡlɑːnsɪŋ","pos":"adjective","senses":[{"en":"hitting something/somebody at an angle, not with full force","cn":"斜擦而过的；击偏的","ex":{"en":"to strike somebody a glancing blow","cn":"以斜击拳击中某人"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"斜擦而过的；击偏的","en":"A glancing blow is one that hits something at an angle rather than from directly in front.","ex":{"en":"The car struck him a glancing blow on the forehead.","cn":"那辆汽车蹭伤了他的前额。"}}]},"examples":[{"en":"to strike somebody a glancing blow","cn":"从侧面给某人一击"}]},"glide":{"media":{"uk":"media/uk/glide__gb_1.mp3","us":"media/us/glide__us_1.mp3"},"oxford":{"phon":"ɡlaɪd","pos":"verb","senses":[{"en":"to move smoothly and quietly, especially as though it takes no effort","cn":"滑行；滑动；掠过","g":"[intransitive]","ex":{"en":"Swans went gliding past.","cn":"天鹅滑行而过。"}},{"en":"to fly using air currents, without the birds moving their wings or the aircraft using the engine","cn":"滑翔","g":"[intransitive]","ex":{"en":"An eagle was gliding high overhead.","cn":"一只鹰在头顶上空翱翔。"}},{"en":"a continuous smooth movement","cn":"滑行；滑动；滑翔","g":"[singular]","ex":{"en":"the graceful glide of a skater","cn":"滑冰者优美的滑行动作"},"pos":"noun"},{"en":"a speech sound made while moving the tongue from one position to another","cn":"滑音","g":"[countable]","lab":"phonetics","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"滑动；滑行；悄悄地走","en":"If you glide somewhere, you move silently and in a smooth and effortless way.","ex":{"en":"Waiters glide between tightly packed tables bearing trays of pasta.","cn":"侍者们端着一盘盘意大利面在拥挤的餐桌之间自如穿行。"}},{"pos":"VERB 动词","cn":"滑翔","en":"When birds or aeroplanes glide, they float on air currents.","ex":{"en":"Our only companion is the wandering albatross, which glides effortlessly and gracefully behind the yacht.","cn":"陪伴我们的仅有那只盘旋的信天翁，它在游艇后面优雅轻盈地翱翔。"}}]},"examples":[{"en":"The plane managed to glide down to the runway.","cn":"飞机终于成功地滑翔降落在跑道上。"},{"en":"An eagle was gliding high overhead.","cn":"一只鹰在头顶上空翱翔。"}]},"global":{"media":{"uk":"media/uk/global__gb_1.mp3","us":"media/us/global__us_1.mp3"},"oxford":{"phon":"ˈɡləʊbl","pos":"adjective","senses":[{"en":"covering or affecting the whole world","cn":"全球的；全世界的","lab":"US English","ex":{"en":"This year the global economy will grow by about 4 per cent.","cn":"今年全球经济将增长 4% 左右。"}},{"en":"considering or including all parts of something","cn":"整体的；全面的；总括的","ex":{"en":"We need to take a more global approach to the problem.","cn":"我们需要更全面地看这个问题。"}},{"en":"operating or applying through the whole of a file, program, etc.","cn":"全局的；全文的","lab":"computing","ex":{"en":"We ran a global search on the database.","cn":"我们在数据库中进行了全程检索。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"全球的；全世界的","en":"You can use global to describe something that happens in all parts of the world or affects all parts of the world.","ex":{"en":"...a global ban on nuclear testing","cn":"全球核试验禁令"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"全面的；整体的；总括的","en":"A global view or vision of a situation is one in which all the different aspects of it are considered.","ex":{"en":"...the global view, the ability to make wider decisions based on a knowledge of all the facts, not just some of them.","cn":"大局观——基于全部而非部分事实作出更加宏观的决定的能力"}}]},"examples":[{"en":"They sent a global email to all staff.","cn":"他们向全体职员发了一封统一的电邮。"},{"en":"We need to take a more global approach to the problem.","cn":"我们需要更全面地看这个问题。"}]},"glittering":{"media":{"uk":"media/uk/glittering__gb_1.mp3","us":"media/us/glittering__us_1.mp3"},"oxford":{"phon":"ˈɡlɪtərɪŋ","pos":"adjective","senses":[{"en":"very impressive and successful","cn":"辉煌的；成功的","ex":{"en":"He has a glittering career ahead of him.","cn":"他前程似锦。"}},{"en":"very impressive and involving rich and successful people","cn":"盛大的；华丽的；众星云集的","ex":{"en":"a glittering occasion/ceremony","cn":"盛会；盛典"}},{"en":"shining brightly with many small flashes of light","cn":"灿烂夺目的；闪闪发光的","ex":{"en":"glittering jewels","cn":"璀璨的宝石"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"辉煌的；成功的","en":"You use glittering to indicate that something is very impressive or successful.","ex":{"en":"...a brilliant school pupil destined for a glittering academic career.","cn":"必将在学术上取得辉煌成就的杰出学生"}}]},"examples":[{"en":"He has a glittering career ahead of him.","cn":"他前程似锦。"},{"en":"a glittering array of stars","cn":"众星云集的盛大场面"}]},"gloomy":{"media":{"uk":"media/uk/gloomy__gb_1.mp3","us":"media/us/gloomy__us_1.mp3"},"oxford":{"phon":"ˈɡluːmi","pos":"adjective","senses":[{"en":"nearly dark, or badly lit in a way that makes you feel sad","cn":"黑暗的；阴暗的；幽暗的","ex":{"en":"a gloomy room/atmosphere","cn":"昏暗的房间；阴沉沉的气氛"}},{"en":"sad and without hope","cn":"忧郁的；沮丧的；无望的","ex":{"en":"a gloomy expression","cn":"沮丧的表情"}},{"en":"without much hope of success or happiness in the future","cn":"前景黯淡的；悲观的","ex":{"en":"a gloomy picture of the country’s economic future","cn":"该国经济前景的黯淡景象"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"昏暗的；幽暗的","en":"If a place is gloomy, it is almost dark so that you cannot see very well.","ex":{"en":"Inside it's gloomy after all that sunshine","cn":"尽管阳光明媚，里面依然暗淡无光。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"忧伤的；沮丧的；无望的","en":"If people are gloomy, they are unhappy and have no hope.","ex":{"en":"Miller is gloomy about the fate of the serious playwright in America.","cn":"米勒对这位严肃剧作家在美国的命运颇为忧虑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"前景黯淡的；悲观的","en":"If a situation is gloomy, it does not give you much hope of success or happiness.","ex":{"en":"...a gloomy picture of an economy sliding into recession","cn":"经济陷入萧条的惨淡景象"}}]},"examples":[{"en":"Suddenly, the future didn't look so gloomy after all.","cn":"突然感到前途似乎并非如此黯淡。"},{"en":"It was a wet and gloomy day.","cn":"那一天下着雨，阴沉沉的。"}]},"gloved":{"media":{"uk":"media/uk/gloved__gb_1.mp3","us":"media/us/gloved__us_1.mp3"},"oxford":{"phon":"ɡlʌvd","pos":"adjective","senses":[{"en":"wearing a glove or gloves","cn":"戴着手套的","ex":{"en":"She laid her gloved hand on my arm.","cn":"她把戴着手套的手放在我的手臂上。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"戴手套的","en":"A gloved hand has a glove on it.","ex":{"en":"His gloved hand held up a computer disk.","cn":"他用那只戴着手套的手拿起一张光盘。"}}]}},"globe":{"media":{"uk":"media/uk/globe__gb_1.mp3","us":"media/us/globe__us_1.mp3","img":["media/ldoce/img/globe.jpg"]},"oxford":{"phon":"ɡləʊb","pos":"noun","senses":[{"en":"the world (used especially to emphasize its size)","cn":"地球，世界（尤用以强调其大）","g":"[singular]","ex":{"en":"tourists from every corner of the globe","cn":"来自世界各地的游客"}},{"en":"an object like a ball in shape with a map of the world on its surface, usually on a stand so that it can be turned","cn":"地球仪","g":"[countable]","ex":{"en":"A dusty old globe stood in the corner of the schoolroom.","cn":"教室的角落里放着一个积满灰尘的旧地球仪。"}},{"en":"a thing that is like a ball in shape","cn":"球体；球状物","g":"[countable]"},{"en":"a light bulb (= the glass part that fits into an electric lamp, etc. to give light when it is switched on)","cn":"灯泡","lab":"Australian English, New Zealand English，，","ex":{"en":"Halogen globes are being replaced with LEDs, which use 80 per cent less energy.","cn":"卤素灯正在被 LED 灯取代，LED 灯的能耗可减少 80%。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"地球，世界（用于强调其广大或某事在许多地区发生）","en":"You can refer to the world as the globe when you are emphasizing how big it is or that something happens in many different parts of it.","ex":{"en":"...bottles of beer from every corner of the globe","cn":"来自世界各个角落的一瓶瓶啤酒"}},{"pos":"N-COUNT 可数名词","cn":"地球仪","en":"A globe is a ball-shaped object with a map of the world on it. It is usually fixed on a stand.","ex":{"en":"...a globe of the world","cn":"世界地球仪"}},{"pos":"N-COUNT 可数名词","cn":"球状物；球体","en":"Any ball-shaped object can be referred to as a globe .","ex":{"en":"The overhead light was covered now with a white globe.","cn":"现在，顶灯已装上了一个白色球状罩子。"}}]},"examples":[{"en":"tourists from every corner of the globe","cn":"来自世界各地的游客"},{"en":"We export our goods all over the globe.","cn":"我们的商品出口到世界各地。"}]},"gloriously":{"oxford":{"phon":"ˈɡlɔːriəsli","pos":"adverb","senses":[{"en":"in a way that deserves or brings great success and makes somebody/something famous","cn":"光荣地：以值得或取得巨大成功并使某人/某事成名的方式","lab":"formal","ex":{"en":"Nelson died gloriously at Trafalgar.","cn":"纳尔逊在特拉法加光荣牺牲。"}},{"en":"in a very beautiful and impressive way","cn":"壮丽的；辉煌的；光辉灿烂的","lab":"formal","ex":{"en":"The show has been gloriously successful.","cn":"该剧取得了巨大成功。"}},{"en":"in a wonderful way","cn":"光荣地：美妙地","ex":{"en":"the gloriously named criminal mastermind, Goldthwait Higginson Dorr","cn":"光荣的犯罪主谋戈德斯韦特·希金森·多尔"}},{"en":"in a pleasantly hot way, with the sun shining","cn":"热的；阳光灿烂的；晴朗的","ex":{"en":"a gloriously sunny day","cn":"令人愉快的晴朗日子"}}]},"media":{"uk":"media/uk/gloriously__gb_1.mp3","us":"media/us/gloriously__us_1.mp3"},"examples":[{"en":"He’s got a great future ahead of him.","cn":""},{"en":"The house has great views.","cn":""}]},"globalization":{"oxford":{"phon":"ˌɡləʊbəlaɪˈzeɪʃn","pos":"noun","senses":[{"en":"the fact that different cultures and economic systems around the world are becoming connected and similar to each other because of the influence of large multinational companies and of improved communication","cn":"全球化，全世界化（世界各地的文化和经济体系日益关联）","lab":"US English"}]},"media":{"uk":"media/uk/globalization__gb_1.mp3","us":"media/us/globalization__us_1.mp3"},"examples":[{"en":"the increasing globalization of world trade","cn":"世界贸易的日益全球化"}]},"glare":{"media":{"uk":"media/uk/glare__gb_1.mp3","us":"media/us/glare__us_1.mp3"},"oxford":{"phon":"ɡleə(r)","pos":"verb","senses":[{"en":"to look at somebody/something in an angry way","cn":"怒目而视","g":"[intransitive]","ex":{"en":"He didn't shout, he just glared at me silently.","cn":"他没有喊叫，只是默默地怒视着我。"}},{"en":"to shine with a very bright, unpleasant light","cn":"发出刺眼的光","g":"[intransitive]"},{"en":"a very bright, unpleasant light","cn":"刺眼的光","g":"[uncountable, singular]","lab":"figurative","ex":{"en":"For a moment she was blinded by the harsh glare of the sun.","cn":"她一时被刺眼的阳光照得眼睛昏花。"},"pos":"noun"},{"en":"a long, angry look","cn":"（长久的）怒视，瞪眼","g":"[countable]","ex":{"en":"to give somebody a hostile glare","cn":"含敌意地瞪着某人"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"怒目而视；瞪眼","en":"If you glare at someone, you look at them with an angry expression on your face.","ex":{"en":"The old woman glared at him","cn":"那个老妇人狠狠地瞪着他。"}},{"pos":"N-COUNT 可数名词","cn":"怒视；瞪眼","en":"A glare is an angry, hard, and unfriendly look.","ex":{"en":"His glasses magnified his irritable glare.","cn":"他那怒不可遏的眼神在眼镜片下显得愈发逼人。"}},{"pos":"VERB 动词","cn":"发出强光；发出刺眼的光芒","en":"If the sun or a light glares, it shines with a very bright light which is difficult to look at.","ex":{"en":"The sunlight glared.","cn":"阳光耀眼。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"强光；刺眼的光","en":"Glare is very bright light that is difficult to look at.","ex":{"en":"...the glare of a car's headlights","cn":"汽车头灯的强光"}},{"pos":"N-SING 单数名词","cn":"密切关注","en":"If someone is in the glare of publicity or public attention, they are constantly being watched and talked about by a lot of people.","ex":{"en":"Norma is said to dislike the glare of publicity","cn":"据说诺尔玛不喜欢被人过多关注。"}}]},"examples":[{"en":"These sunglasses are designed to reduce glare.","cn":"这些太阳镜是为减少刺眼的强光而设计的。"},{"en":"( figurative ) The divorce was conducted in the full glare of publicity (= with continuous attention from newspapers and television).","cn":"这桩离婚案是在媒体的密切关注下进行的。"}]},"glass":{"media":{"img":["media/pic/cupsandglasses_diningroom_comp.jpg","media/thumb/tumbler.jpg"],"uk":"media/uk/glass__gb_1.mp3","us":"media/us/glass__us_1.mp3"},"oxford":{"phon":"ɡlɑːs","pos":"noun","senses":[{"en":"a hard, usually clear, substance used, for example, for making windows and bottles","cn":"玻璃","g":"[uncountable]","sc":"clear substance","ex":{"en":"a sheet/pane of glass","cn":"一片玻璃；一块窗玻璃"}},{"en":"a container made of glass, used for drinking out of","cn":"玻璃杯；酒杯","g":"[countable]","sc":"for drinking","ex":{"en":"He poured orange juice into a glass.","cn":"他把橙汁倒进玻璃杯里。"}},{"en":"the contents of a glass","cn":"一杯（的量）","g":"[countable]","sc":"for drinking","ex":{"en":"He drank three whole glasses.","cn":"他喝了满满三杯。"}},{"en":"two lenses in a frame that rests on the nose and ears. People wear glasses in order to be able to see better or to protect their eyes from bright light.","cn":"眼镜","g":"[plural]","lab":"North American English also","sc":"for eyes","ex":{"en":"a pair of glasses","cn":"一副眼镜"}},{"en":"objects made of glass","cn":"玻璃器皿；玻璃制品","g":"[uncountable]","sc":"glass objects","ex":{"en":"We keep all our glass and china in this cupboard.","cn":"我们把所有玻璃器皿和瓷器都放在这个橱里。"}},{"en":"a protecting cover made of glass on a watch, picture or photograph frame, fire alarm, etc.","cn":"玻璃保护面；玻璃（镜）框；（火灾警报器的）玻璃罩","g":"[singular]","sc":"glass objects","ex":{"en":"In case of emergency, break the glass and press the button.","cn":"如遇紧急情况，击碎玻璃罩按下按钮。"}},{"en":"a mirror","cn":"镜子","g":"[countable, usually singular]","lab":"old-fashioned","sc":"mirror"},{"en":"a barometer","cn":"气压表；晴雨表","g":"[singular]","sc":"barometer"},{"en":"to hit somebody in the face with a glass","cn":"用玻璃杯击（某人）的脸部","pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"玻璃","en":"Glass is a hard transparent substance that is used to make things such as windows and bottles.","ex":{"en":"...a pane of glass.","cn":"一块玻璃"}},{"pos":"N-COUNT 可数名词","cn":"玻璃杯","en":"A glass is a container made from glass, which you can drink from and which does not have a handle.","ex":{"en":"Grossman raised the glass to his lips.","cn":"格罗斯曼把杯子举到唇边。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"玻璃制品","en":"Glass is used to mean objects made of glass, for example drinking containers and bowls.","ex":{"en":"There's a glittering array of glass to choose from at markets.","cn":"市场上有很多晶莹闪亮的玻璃制品可供挑选。"}},{"pos":"N-PLURAL 复数名词","cn":"眼镜","en":"Glasses are two lenses in a frame that some people wear in front of their eyes in order to help them see better.","ex":{"en":"He took off his glasses.","cn":"他摘掉眼镜。"}}]},"examples":[{"en":"We keep all our glass and china in this cupboard.","cn":"我们把所有玻璃器皿和瓷器都放在这个橱里。"},{"en":"She has a fine collection of Bohemian glass.","cn":"她收藏了一批做工精细的波希米亚玻璃制品。"}]},"glossary":{"oxford":{"phon":"ˈɡlɒsəri","pos":"noun","senses":[{"en":"a list of technical or special words, especially those in a particular text, explaining their meanings","cn":"术语汇编；词汇表","ex":{"en":"a glossary of financial terms","cn":"金融术语词汇表"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"术语汇编；词汇表","en":"A glossary of special, unusual, or technical words or expressions is an alphabetical list of them giving their meanings, for example at the end of a book on a particular subject."}]},"media":{"uk":"media/uk/glossary__gb_1.mp3","us":"media/us/glossary__us_2.mp3"}},"gloom":{"media":{"uk":"media/uk/gloom__gb_1.mp3","us":"media/us/gloom__us_1.mp3"},"oxford":{"phon":"ɡluːm","pos":"noun","senses":[{"en":"a feeling of being sad and without hope","cn":"忧郁；愁闷；无望","g":"[uncountable, singular]","ex":{"en":"The gloom deepened as the election results came in.","cn":"选举结果陆续传来，失落的情绪越来越重。"}},{"en":"almost total darkness","cn":"幽暗；黑暗；昏暗","g":"[uncountable]","lab":"literary","ex":{"en":"We watched the boats come back in the gathering gloom.","cn":"我们注视着船只在越来越浓的暮色中返航。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"阴暗；昏暗","en":"The gloom is a state of near darkness.","ex":{"en":"...the gloom of a foggy November morning","cn":"11月份一个雾蒙蒙的早晨，天空昏暗阴沉"}},{"pos":"N-UNCOUNT 不可数名词","cn":"忧郁；愁闷；无望","en":"Gloom is a feeling of sadness and lack of hope.","ex":{"en":"...the deepening gloom over the economy.","cn":"对经济的忧虑日益加重"}}]},"examples":[{"en":"The gloom deepened as the election results came in.","cn":"选举结果陆续传来，失落的情绪越来越重。"},{"en":"We watched the boats come back in the gathering gloom.","cn":"我们注视着船只在朦胧暮色中返航。"}]},"glacier":{"oxford":{"phon":"ˈɡlæsiə(r)","pos":"noun","senses":[{"en":"a slow-moving mass or river of ice, formed from snow on mountains or near the North Pole or South Pole","cn":"冰川"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"冰川；冰河","en":"A glacier is an extremely large mass of ice which moves very slowly, often down a mountain valley."}]},"media":{"uk":"media/uk/glacier__gb_1.mp3","us":"media/us/glacier__us_1.mp3"}},"glorious":{"media":{"uk":"media/uk/glorious__gb_1.mp3","us":"media/us/glorious__us_1.mp3"},"oxford":{"phon":"ˈɡlɔːriəs","pos":"adjective","senses":[{"en":"deserving or bringing great success and making somebody/something famous","cn":"辉煌的；光荣的；荣耀的","lab":"formal","ex":{"en":"We congratulate you on this glorious victory.","cn":"我们祝贺你取得了这一辉煌的胜利。"}},{"en":"very beautiful and impressive","cn":"壮丽的；辉煌的；光辉灿烂的","ex":{"en":"We sat on the beach and gazed at the glorious sunset.","cn":"我们坐在海滩上，凝望着瑰丽的晚霞。"}},{"en":"hot, with the sun shining","cn":"热的；阳光灿烂的；晴朗的","ex":{"en":"They had three weeks of glorious sunshine.","cn":"他们度过了三周阳光灿烂的日子。"}},{"en":"extremely pleasant","cn":"极其令人愉快的；极为宜人的","ex":{"en":"a glorious trip to Rome","cn":"极为享受的罗马之行"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宏伟的；壮丽的","en":"Something that is glorious is very beautiful and impressive.","ex":{"en":"...a glorious rainbow in the air","cn":"空中壮观的彩虹"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人愉快的；美好的","en":"If you describe something as glorious, you are emphasizing that it is wonderful and it makes you feel very happy.","ex":{"en":"The win revived glorious memories of his championship-winning days","cn":"这次胜利勾起了他对往昔那些夺冠岁月的美好回忆。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"辉煌的；光荣的；荣耀的","en":"A glorious career, victory, or occasion involves great fame or success.","ex":{"en":"Harrison had a glorious career spanning more than six decades","cn":"哈里森辉煌的职业生涯长达60多年。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（天气）晴好的，阳光灿烂的","en":"Glorious weather is hot and sunny.","ex":{"en":"I got dressed and emerged into glorious sunshine","cn":"我穿好衣服，走进灿烂的阳光中。"}}]},"examples":[{"en":"They had three weeks of glorious sunshine.","cn":"他们度过了三周阳光灿烂的日子。"},{"en":"a glorious chapter in our country's history","cn":"我国历史上光辉的一页"}]},"glance":{"media":{"uk":"media/uk/glance__gb_1.mp3","us":"media/us/glance__us_1.mp3"},"oxford":{"phon":"ɡlɑːns","pos":"verb","senses":[{"en":"to look quickly at something/somebody","cn":"瞥一眼；匆匆一看；扫视","g":"[intransitive]","ex":{"en":"She glanced at her watch.","cn":"她匆匆看了看表。"}},{"en":"to read something quickly and not carefully or completely","cn":"浏览；翻阅","g":"[intransitive]","ex":{"en":"I only had time to glance at my emails.","cn":"我只来得及粗略地看了一下电邮。"}},{"en":"a quick look","cn":"匆匆一看；一瞥；扫视","ex":{"en":"to take/have a glance at the newspaper headlines","cn":"匆匆看一眼报纸的大标题"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"瞥；迅速地看一眼","en":"If you glance at something or someone, you look at them very quickly and then look away again immediately.","ex":{"en":"He glanced at his watch","cn":"他匆匆看了一下手表。"}},{"pos":"VERB 动词","cn":"浏览","en":"If you glance through or at a newspaper, report, or book, you spend a short time looking at it without reading it very carefully.","ex":{"en":"I picked up the phone book and glanced through it","cn":"我拿起电话簿，匆匆扫了一遍。"}},{"pos":"N-COUNT 可数名词","cn":"一瞥；扫视","en":"A glance is a quick look at someone or something.","ex":{"en":"Trevor and I exchanged a glance.","cn":"特雷弗和我迅速交换了一下眼色。"}},{"pos":"PHRASE 短语","cn":"立刻；一眼就","en":"If you see something at a glance, you see or recognize it immediately, and without having to think or look carefully.","ex":{"en":"One could tell at a glance that she was a compassionate person.","cn":"一眼就能看出她很有同情心。"}},{"pos":"PHRASE 短语","cn":"乍一看；乍看上去","en":"If you say that something is true or seems to be true at first glance, you mean that it seems to be true when you first see it or think about it, but that your first impression may be wrong.","ex":{"en":"At first glance, organic farming looks much more expensive for the farmer.","cn":"乍一看，有机耕作对农民而言似乎花费大多了。"}},{"pos":"PHRASE 短语","cn":"偷偷地看一眼；偷瞥","en":"If you steal a glance at someone or something, you look at them quickly so that nobody sees you looking.","ex":{"en":"He stole a glance at the clock behind her.","cn":"他偷偷地看了一眼她背后的钟。"}},{"pos":"","cn":"","en":"相关词组：glance off"}]},"examples":[{"en":"I glanced up quickly to see who had come in.","cn":"我迅速抬头瞥了一眼看是谁进来了。"},{"en":"I only had time to glance at the newspapers.","cn":"我只来得及浏览了一下报纸。"}]},"glue":{"oxford":{"phon":"ɡluː","pos":"noun","senses":[{"en":"a sticky substance that is used for joining things together","cn":"胶；胶水","lab":"figurative","ex":{"en":"All you will need is a sharp knife and a tube of glue.","cn":"你只需要一把锋利的刀和一管胶水。"}},{"en":"to join two things together using glue","cn":"（用胶水）黏合，粘牢，粘贴","ex":{"en":"She glued the label onto the box.","cn":"她把标签贴在箱子上。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"胶；胶水","en":"Glue is a sticky substance used for joining things together, often for repairing broken things.","ex":{"en":"...a tube of glue.","cn":"一管胶水"}},{"pos":"VERB 动词","cn":"用胶水粘","en":"If you glue one object to another, you stick them together using glue.","ex":{"en":"Glue the fabric around the window","cn":"用胶水把布料粘在窗户周围。"}},{"pos":"V-PASSIVE 被动动词","cn":"完全吸引；使专注于","en":"If you say that someone is glued to something, you mean that they are giving it all their attention.","ex":{"en":"They are all glued to the Olympic Games.","cn":"他们都被奥运会吸引住了。"}}]},"media":{"img":["media/pic/stationery_supplies_comp.jpg","media/thumb/gluestick.jpg"],"uk":"media/uk/glue__gb_1.mp3","us":"media/us/glue__us_1.mp3"},"examples":[{"en":"Glue the two pieces of cardboard together.","cn":"把这两张硬纸板粘在一起。"},{"en":"Her eyes were glued to the screen (= she did not stop watching it).","cn":"她目不转睛地盯着屏幕。"}]},"glow":{"oxford":{"phon":"ɡləʊ","pos":"verb","senses":[{"en":"to produce a steady light that is not very bright","cn":"发微光；发出暗淡的光","g":"[intransitive]","ex":{"en":"The embers still glowed in the hearth.","cn":"余烬仍在炉膛里发出暗淡的光。"}},{"en":"to look or feel warm or pink, especially after exercise or because you are excited, embarrassed, etc.","cn":"（尤指运动后或因情绪激动、尴尬等而）发红，发热，显得红，感觉热","g":"[intransitive]","ex":{"en":"Her cheeks were glowing.","cn":"她双颊绯红。"}},{"en":"to look very pleased or satisfied","cn":"喜形于色；心满意足","g":"[intransitive]","ex":{"en":"She was positively glowing with pride.","cn":"她一副踌躇满志的样子。"}},{"en":"to appear a strong, warm colour","cn":"色彩鲜艳；绚丽夺目","g":"[intransitive]","ex":{"en":"The countryside glowed with autumn colours.","cn":"乡村里秋色绚烂。"}},{"en":"a steady light that is not too bright, like the light from a fire that has stopped producing flames","cn":"微弱稳定的光；暗淡的光","ex":{"en":"The city was just a red glow on the horizon.","cn":"城市看上去只是地平线上的一片红光。"},"pos":"noun"},{"en":"the pink colour in your face when you have been doing exercise or feel happy and excited","cn":"（运动、高兴或激动时）满面红光，容光焕发，满脸通红","ex":{"en":"The fresh air had brought a healthy glow to her cheeks.","cn":"新鲜空气使她两颊红润，精神焕发。"},"pos":"noun"},{"en":"a gold or red colour","cn":"金色；红色","ex":{"en":"the glow of autumn leaves","cn":"秋叶红似火"},"pos":"noun"},{"en":"a feeling of pleasure","cn":"喜悦；愉快","ex":{"en":"When she looked at her children, she felt a glow of pride.","cn":"看见自己的孩子，她就感到由衷的自豪。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"微弱稳定的光；暗淡的光","en":"A glow is a dull, steady light, for example the light produced by a fire when there are no flames.","ex":{"en":"...the cigarette's red glow","cn":"香烟发出的红光"}},{"pos":"N-SING 单数名词","cn":"（脸上的）红光，红晕，红润","en":"A glow is a pink colour on a person's face, usually because they are healthy or have been exercising.","ex":{"en":"The moisturiser gave my face a healthy glow that lasted all day.","cn":"涂了润肤霜，我的脸一整天都红润亮泽。"}},{"pos":"N-SING 单数名词","cn":"一股，满腔（满足感等）","en":"If you feel a glow of satisfaction or achievement, you have a strong feeling of pleasure because of something that you have done or that has happened.","ex":{"en":"Exercise will give you a glow of satisfaction at having achieved something","cn":"运动将让你体会到一种有所成就的无比喜悦感。"}},{"pos":"VERB 动词","cn":"发微弱而稳定的光；发暗淡的光","en":"If something glows, it produces a dull, steady light.","ex":{"en":"The night lantern glowed softly in the darkness","cn":"晚上点亮的灯笼在黑暗中发出柔和的光。"}},{"pos":"VERB 动词","cn":"色彩鲜艳；绚丽夺目；洋溢着（某种特征）","en":"If a place glows with a colour or a quality, it is bright, attractive, and colourful.","ex":{"en":"Used together these colours will make your interiors glow with warmth and vitality.","cn":"这些颜色搭配使用会使你屋子里暖意融融，充满生机。"}},{"pos":"VERB 动词","cn":"发光；泛光","en":"If something glows, it looks bright because it is reflecting light.","ex":{"en":"The instruments glowed in the bright orange light","cn":"明亮的橙色灯光下，这些乐器闪闪发光。"}},{"pos":"VERB 动词","cn":"（皮肤由于健康、激动或运动）发红，泛红晕，容光焕发","en":"If someone's skin glows, it looks pink because they are healthy or excited, or have been doing physical exercise.","ex":{"en":"Her freckled skin glowed with health again.","cn":"她长有雀斑的皮肤又泛出了健康的红光。"}},{"pos":"VERB 动词","cn":"洋溢着，散发出（某种情感）","en":"If someone glows with an emotion such as pride or pleasure, the expression on their face shows how they feel.","ex":{"en":"The expectant mothers that Amy had encountered positively glowed with pride.","cn":"埃米遇见的准妈妈们个个洋溢着自豪和喜悦。"}}]},"media":{"uk":"media/uk/glow__gb_1.mp3","us":"media/us/glow__us_1.mp3"},"examples":[{"en":"There was no light except for the occasional glow of a cigarette.","cn":"除偶尔有香烟的微弱红光外没有一点亮光。"},{"en":"The strap has a fluorescent coating that glows in the dark.","cn":"皮带面上有一层荧光在黑暗中微微发光。"}]},"glimpse":{"media":{"uk":"media/uk/glimpse__gb_1.mp3","us":"media/us/glimpse__us_1.mp3"},"oxford":{"phon":"ɡlɪmps","pos":"noun","senses":[{"en":"a sight of somebody/something for a very short time, when you do not see the person or thing completely","cn":"一瞥；一看","ex":{"en":"He caught a glimpse of her in the crowd.","cn":"他一眼瞥见她在人群里。"}},{"en":"a short experience of something that helps you to understand it","cn":"短暂的感受（或体验、领会）","ex":{"en":"The programme gives us a rare glimpse of a great artist at work.","cn":"这个节目使我们难得地认识到伟大艺术家工作时的情况。"}},{"en":"to see somebody/something for a moment, but not very clearly","cn":"瞥见；看一眼","ex":{"en":"He'd glimpsed her through the window as he passed.","cn":"他路过时透过窗户瞥见了她。"},"pos":"verb"},{"en":"to start to understand something","cn":"开始领悟；开始认识到","ex":{"en":"Suddenly she glimpsed the truth about her sister.","cn":"她突然开始了解到她姐姐的真实情况。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一瞥；扫视","en":"If you get a glimpse of someone or something, you see them very briefly and not very well.","ex":{"en":"Some of the fans had waited 24 hours outside the Hyde Park Hotel to catch a glimpse of their heroine.","cn":"为了一睹女主角的风采，一些追星族已经在海德公园饭店外守候了24个小时。"}},{"pos":"VERB 动词","cn":"瞥见","en":"If you glimpse someone or something, you see them very briefly and not very well.","ex":{"en":"She glimpsed a group of people standing on the bank of a river.","cn":"她瞥见一群人站在河岸边。"}},{"pos":"N-COUNT 可数名词","cn":"短暂的感受；初步的认识","en":"A glimpse of something is a brief experience of it or an idea about it that helps you understand or appreciate it better.","ex":{"en":"As university campuses become increasingly multi-ethnic, they offer a glimpse of the conflicts society will face tomorrow.","cn":"大学校园变得日益多种族化，通过校园可以对未来社会将要面对的诸多冲突有一个初步的认识。"}}]},"examples":[{"en":"The programme gives us a rare glimpse of a great artist at work.","cn":"这个节目使我们难得地认识到伟大艺术家工作时的情况。"},{"en":"a fascinating glimpse into life in the ocean","cn":"对海洋生物的一次短暂而动人心魄的感受"}]},"gladly":{"media":{"uk":"media/uk/gladly__gb_1.mp3","us":"media/us/gladly__us_1.mp3"},"oxford":{"phon":"ˈɡlædli","pos":"adverb","senses":[{"en":"willingly","cn":"乐意地；情愿地","ex":{"en":"I would gladly pay extra for a good seat.","cn":"我很愿意额外付费坐好座位。"}},{"en":"happily; with thanks","cn":"高兴地；欣然地；感激地","ex":{"en":"When I offered her my seat, she accepted it gladly.","cn":"我把座位让给她时，她欣然接受了。"}}]},"examples":[{"en":"When I offered her my seat, she accepted it gladly.","cn":"我把座位让给她时，她欣然接受了。"},{"en":"I would gladly pay extra for a good seat.","cn":"我情愿额外付费坐好座位。"}]},"glanced":{"oxford":{"phon":"ɡlɑːns","pos":"verb","senses":[{"en":"to look quickly at sth/sb","cn":"瞥一眼；匆匆一看；扫视"},{"en":"to read sth quickly and not thoroughly","cn":"浏览；粗略地看"}]}},"globes":{"oxford":{"phon":"ɡləʊb","pos":"noun","senses":[{"en":"an object shaped like a ball with a map of the world on its surface, usually on a stand so that it can be turned","cn":"地球仪"},{"en":"the world (used especially to emphasize its size)","cn":"地球，世界（尤用以强调其大）"}]}},"gleamed":{"oxford":{"phon":"ɡliːm","pos":"verb","senses":[{"en":"to shine with a pale clear light","cn":"发微光；隐约闪光；闪烁"},{"en":"to look very clean or bright","cn":"显得光洁明亮"}]}},"glances":{"oxford":{"phon":"ɡlɑːns","pos":"verb","senses":[{"en":"to look quickly at sth/sb","cn":"瞥一眼；匆匆一看；扫视"},{"en":"to read sth quickly and not thoroughly","cn":"浏览；粗略地看"}]}},"glasses":{"oxford":{"phon":"ɡlɑːs","pos":"noun","senses":[{"en":"a hard, usually transparent, substance used, for example, for making windows and bottles","cn":"玻璃"},{"en":"( often in compounds","cn":"常构成复合词 ) a container made of glass, used for drinking out of 玻璃杯；酒杯"}]},"media":{"img":["media/ldoce/img/glasses.jpg"]}},"glimpses":{"oxford":{"phon":"ɡlɪmps","pos":"noun","senses":[{"en":"a look at sb/sth for a very short time, when you do not see the person or thing completely","cn":"一瞥；一看"},{"en":"a short experience of sth that helps you to understand it","cn":"短暂的感受（或体验、领会）"}]}},"globalized":{"oxford":{"phon":"ˈɡləʊbəlaɪz","pos":"verb","senses":[{"en":"( economics","cn":"经 ) if sth, for example a business company, globalizes or is globalized , it operates all around the world （使）全球化，全世界化"}]}},"glimpsed":{"oxford":{"phon":"ɡlɪmps","pos":"noun","senses":[{"en":"a look at sb/sth for a very short time, when you do not see the person or thing completely","cn":"一瞥；一看"},{"en":"a short experience of sth that helps you to understand it","cn":"短暂的感受（或体验、领会）"}]}},"glided":{"oxford":{"phon":"ɡlaɪd","pos":"verb","senses":[{"en":"to move smoothly and quietly, especially as though it takes no effort","cn":"滑行；滑动；掠过"},{"en":"to fly using air currents, without the birds moving their wings or the aircraft using the engine","cn":"滑翔"}]}},"glassed":{"oxford":{"phon":"ɡlɑːs","pos":"noun","senses":[{"en":"a hard, usually transparent, substance used, for example, for making windows and bottles","cn":"玻璃"},{"en":"( often in compounds","cn":"常构成复合词 ) a container made of glass, used for drinking out of 玻璃杯；酒杯"}]}},"glistening":{"oxford":{"phon":"ˈɡlɪsn","pos":"verb","senses":[{"en":"to shine","cn":"闪光；闪亮"}]}},"gloss":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"光泽；色泽；光亮","en":"A gloss is a bright shine on the surface of something.","ex":{"en":"Rain produced a black gloss on the asphalt.","cn":"雨后的柏油路面显得黑亮黑亮的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"虚假的外表；假象；虚饰","en":"Gloss is an appearance of attractiveness or good quality which sometimes hides less attractive features or poor quality.","ex":{"en":"Television commercials might seem more professional but beware of mistaking the gloss for the content.","cn":"电视广告看上去或许更加专业，但要当心，不要把表象误以为真。"}},{"pos":"N-SING 单数名词","cn":"粉饰；掩饰","en":"If you put a gloss on a bad situation, you try to make it seem more attractive or acceptable by giving people a false explanation or interpretation of it.","ex":{"en":"He used his diary to put a fine gloss on the horrors the regime perpetrated","cn":"他假借日记对该政权犯下的恐怖罪行巧加粉饰。"}},{"pos":"N-MASS 物质名词","cn":"同gloss paint","en":"Gloss is the same as gloss paint ."},{"pos":"N-MASS 物质名词","cn":"唇彩；亮彩化妆品","en":"Gloss is a type of shiny make-up.","ex":{"en":"She brushed gloss on to her eyelids.","cn":"她在眼睑上涂了些亮彩眼影。"}},{"pos":"VERB 动词","cn":"解释；诠释；说明","en":"If you gloss a difficult word or idea, you provide an explanation of it.","ex":{"en":"Older editors glossed 'drynke' as 'love-potion'.","cn":"老编辑将drynke注释为love-potion（春药）。"}},{"pos":"","cn":"","en":"相关词组：gloss over"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a soft, smooth, shiny appearance","cn":""},{"en":"the shiny appearance of something that is of good quality or in good condition","cn":""},{"en":"a soft, attractive, shiny appearance","cn":""}]},"vocab":{"pos":"1 n v 2 v n","senses":[{"en":"A gloss is a shiny finish on an object. It’s also an explanation about a word or phrase. Right now, you’re reading a gloss on the word gloss ."}]},"collocations":{"phrases":["ADJ. clear, high Use a high gloss paint. | healthy, natural Your hair has lost its natural gloss.","VERB + GLOSS add We used a gel to add gloss to her hair. | lose","GLOSS + NOUN finish, paint, varnish furniture with a dark gloss finish"]},"media":{"uk":"media/ldoce/hwd/bre/d/gloss_n0205.mp3","us":"media/ldoce/hwd/ame/5/gloss1.mp3"},"examples":[{"en":"Beneath the gloss of success was a tragic private life.","cn":"在成功的外表下面却隐藏着悲惨的私人生活。"},{"en":"You can have the photos with either a gloss or a matt finish.","cn":"你可选择用光面或布面相纸洗印这些照片。"}],"oxford":{"phon":"ɡlɒs","pos":"noun","senses":[{"en":"a shine on a smooth surface","cn":"（平滑表面上的）光泽，光亮","g":"[uncountable, singular]","ex":{"en":"paper with a high gloss on one side","cn":"单面上光纸"}},{"en":"a substance designed to make something shiny","cn":"用以产生光泽的物质","g":"[uncountable]","ex":{"en":"lip gloss","cn":"唇彩"}},{"en":"paint which, when dry, has a hard shiny surface","cn":"光泽涂料；亮光漆","g":"[uncountable]","ex":{"en":"two coats of gloss","cn":"两层亮光漆"}},{"en":"an attractive appearance that is only on the surface and hides what is not so attractive","cn":"虚假的外表；虚饰","g":"[uncountable, singular]","ex":{"en":"Beneath the gloss of success was a tragic private life.","cn":"在成功的外表下面却隐藏着悲惨的私人生活。"}},{"en":"a way of explaining something to make it seem more attractive or acceptable","cn":"精彩的解释（或阐述）","g":"[countable]","ex":{"en":"The director puts a Hollywood gloss on the civil war.","cn":"导演对内战作了一番好莱坞式的精彩阐述。"}},{"en":"a note or comment added to a piece of writing to explain a difficult word or phrase","cn":"注释；评注","g":"[countable]"},{"en":"to add a note or comment to a piece of writing to explain a difficult word or idea","cn":"在…上作注释（或评注）","pos":"verb"}]}},"gland":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"腺","en":"A gland is an organ in the body which produces chemical substances for the body to use or get rid of.","ex":{"en":"...the hormones secreted by our endocrine glands.","cn":"人体内分泌腺分泌的荷尔蒙"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an organ of the body which produces a substance that the body needs, such as hormone s , sweat , or saliva","cn":"腺"}]},"collocations":{"phrases":["ADJ. enlarged, swollen She's gone to bed with swollen glands and a temperature. | adrenal, endocrine, exocrine, pineal, pituitary, prostate,","GLAND + VERB release sth, secrete sth"]},"media":{"uk":"media/ldoce/hwd/bre/1/gland0205.mp3","us":"media/ldoce/hwd/ame/2/gland.mp3"},"examples":[{"en":"Her glands are swollen.","cn":"她的腺体肿胀。"},{"en":"a snake's poison glands","cn":"蛇的毒腺"}],"oxford":{"phon":"ɡlænd","pos":"noun","senses":[{"en":"an organ in a person’s or an animal’s body that produces a substance for the body to use; a part in the body that is similar to this, especially a lymph node","cn":"腺","ex":{"en":"a snake’s poison glands","cn":"蛇的毒腺"}}]}},"glint":{"collins":{"senses":[{"pos":"VERB 动词","cn":"闪闪发光；闪亮","en":"If something glints, it produces or reflects a quick flash of light.","ex":{"en":"The sea glinted in the sun","cn":"阳光下的海面波光粼粼。"}},{"pos":"N-COUNT 可数名词","cn":"闪光；闪烁","en":"A glint is a quick flash of light.","ex":{"en":"...a glint of silver.","cn":"银光闪闪"}},{"pos":"VERB 动词","cn":"（眼睛）闪光，闪动，闪亮","en":"If someone's eyes glint, they shine and express a particular emotion.","ex":{"en":"Her eyes glinted wildly","cn":"她眼里流露出激动的神情。"}},{"pos":"N-SING 单数名词","cn":"（眼神的）闪光，闪动，闪亮","en":"A glint in someone's eyes is a brightness that expresses a particular emotion.","ex":{"en":"He came up to me with the glint of triumph in his eye.","cn":"他向我走来，眼里闪现出一丝胜利的神情。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something sparkles, it shines with many small bright points when light is on it","cn":""},{"en":"to shine by reflecting the light – used especially about smooth clean surfaces, or about someone’s eyes or teeth","cn":""},{"en":"to shine with quick flashes of light","cn":""}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"A glint is a brief flash or flicker of light. You might enjoy gazing at the glint of light on the water as you lie on the beach in the summer time."}]},"collocations":{"phrases":["ADV. angrily His eyes glinted angrily.","PREP. with Her eyes glinted with amusement."]},"media":{"uk":"media/ldoce/hwd/bre/1/glint_n0205.mp3","us":"media/ldoce/hwd/ame/3/glint1.mp3"},"examples":[{"en":"Her eyes glinted angrily.","cn":"她眼睛里闪射着愤怒的目光。"},{"en":"The sun glinted on the windows.","cn":"太阳照在窗户上闪闪发光。"}],"oxford":{"phon":"ɡlɪnt","pos":"verb","senses":[{"en":"to produce small bright flashes of light","cn":"闪光；闪亮","g":"[intransitive]","ex":{"en":"The sea glinted in the moonlight.","cn":"月色中海面上波光粼粼。"}},{"en":"if a person’s eyes glint with a particular emotion, or an emotion glints in a person’s eyes, the person shows that emotion, which is usually a strong one","cn":"（眼睛）流露出（强烈情感）；（强烈情感在眼中）闪现","g":"[intransitive]","ex":{"en":"Her eyes glinted angrily.","cn":"她眼睛里闪射着愤怒的目光。"}},{"en":"a sudden flash of light or colour shining from a bright surface","cn":"闪光；闪亮","ex":{"en":"the glint of the sun on the water","cn":"太阳照在水上的闪光"},"pos":"noun"},{"en":"an expression in somebody’s eyes showing a particular emotion, often a negative one","cn":"（眼睛里某种感情，常指负面感情的）闪现","ex":{"en":"He had a wicked glint in his eye.","cn":"他眼睛里闪着邪恶的神色。"},"pos":"noun"}]}},"glamorous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"富有魅力的；迷人的；令人向往的","en":"If you describe someone or something as glamorous, you mean that they are more attractive, exciting, or interesting than ordinary people or things.","ex":{"en":"...some of the world's most beautiful and glamorous women","cn":"全世界最漂亮迷人的一些女性"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this about a woman who is extremely attractive in a way that is fairly unusual and special, so that people notice and admire her","cn":""},{"en":"use this about a woman who is nice to look at and has an attractive face and body","cn":""},{"en":"use this about a young woman or girl who has an attractive face and is good-looking, but not in an unusual way","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Movie stars look glamorous when they walk down the red carpet in their designer gowns. Glamorous means full of glamour, beauty, and excitement."}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound | become | consider sth, regard sth as, see sth as Canoeing is not seen as glamorous in the way that skiin","ADV. really, very | less than, not exactly, not in the least Working in publishing turned out to be less than glamorous. | quite, rather"]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdeglamorous.mp3","us":"media/ldoce/hwd/ame/7/laadglamorous.mp3"},"examples":[{"en":"glamorous movie stars","cn":"富有魅力的影星"},{"en":"a glamorous job","cn":"令人向往的工作"}],"oxford":{"phon":"ˈɡlæmərəs","pos":"adjective","senses":[{"en":"especially attractive and exciting, and different from ordinary things or people","cn":"特别富有魅力的；富于刺激的；独特的","ex":{"en":"glamorous movie stars","cn":"富有魅力的影星"}}]}},"gleam":{"collins":{"senses":[{"pos":"VERB 动词","cn":"闪光；闪烁","en":"If an object or a surface gleams, it reflects light because it is shiny and clean.","ex":{"en":"His black hair gleamed in the sun.","cn":"他的黑发在阳光下闪着光泽。"}},{"pos":"N-SING 单数名词","cn":"反光；闪光","en":"You can refer to the light reflected from something as a gleam .","ex":{"en":"...the gleam of the dark river","cn":"黑黝黝的河流上闪烁的波光"}},{"pos":"VERB 动词","cn":"（日、月等）发微光；闪烁","en":"If a light or the sun or moon gleams, it shines faintly.","ex":{"en":"Neon lights gleamed in the deepening mists.","cn":"霓虹灯在渐浓的雾霭中隐约闪烁。"}},{"pos":"N-COUNT 可数名词","cn":"微光；一丝光线","en":"A gleam of light is a pale, clear light.","ex":{"en":"...the gleam of the headlights.","cn":"汽车头灯的微光"}},{"pos":"VERB 动词","cn":"（眼睛）闪闪发亮，闪烁着光芒","en":"If your eyes gleam, they look bright and show that you are excited or happy.","ex":{"en":"His eyes gleamed almost wickedly.","cn":"他狡黠的双眼闪闪发亮。"}},{"pos":"N-SING 单数名词","cn":"（情感的）表露，闪现","en":"If someone has a gleam in their eye, their eyes show a particular feeling.","ex":{"en":"There was a gleam in her eye when she looked at me.","cn":"她朝我看时眼中流露出某种神情。"}},{"pos":"N-COUNT 可数名词","cn":"一丝；一线；少许","en":"A gleam of something is a faint sign of it.","ex":{"en":"There was a gleam of hope for a peaceful settlement.","cn":"还有一线和平解决的希望。"}},{"pos":"PHRASE 短语","cn":"尚未成形的想法；蒙眬的想法","en":"If you say that something is only a gleam in someone's eye at present, you mean that it is only being planned or considered, and has not yet been properly begun.","ex":{"en":"The product is still only a gleam in an engineer's eye.","cn":"该产品还只是工程师头脑中尚未成形的想法。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something sparkles, it shines with many small bright points when light is on it","cn":""},{"en":"to shine by reflecting the light – used especially about smooth clean surfaces, or about someone’s eyes or teeth","cn":""},{"en":"to shine with quick flashes of light","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A gleam is a bright flash of light. If you were lost on a dark, stormy night, you'd be hugely relieved to see the gleam of a roadside diner's sign up ahead."}]},"collocations":{"phrases":["ADV. dully, faintly, softly Th e knife's blade gleamed dully in th e dark .","PREP. with The long oak table gleamed with polish.","PHRASES gleam golden, white, etc. The pebble beach gleamed white in the moonlight."]},"media":{"uk":"media/ldoce/hwd/bre/2/gleam_n0205.mp3","us":"media/ldoce/hwd/ame/1/gleam1.mp3"},"examples":[{"en":"Her teeth gleamed white against the tanned skin of her face.","cn":"她的牙齿在褐色脸膛映衬下显得洁白明亮。"},{"en":"The house was gleaming with fresh white paint.","cn":"房子刚刷过白漆，显得光洁明亮。"}],"oxford":{"phon":"ɡliːm","pos":"verb","senses":[{"en":"to shine with a pale clear light","cn":"发微光；隐约闪光；闪烁","g":"[intransitive]","ex":{"en":"The moonlight gleamed on the water.","cn":"月光照在水面上泛起粼粼波光。"}},{"en":"to look very clean or bright","cn":"显得光洁明亮","g":"[intransitive]","ex":{"en":"The house was gleaming with fresh white paint.","cn":"房子刚刷过白漆，显得光洁明亮。"}},{"en":"if a person’s eyes gleam with a particular emotion, or an emotion gleams in a person’s eyes, the person shows that emotion","cn":"（眼睛）表露出，流露出；（在眼中）闪现","g":"[intransitive]","ex":{"en":"His eyes gleamed with amusement.","cn":"他眼睛里流露出愉悦的神情。"}},{"en":"a pale clear light, often reflected from something","cn":"微光（常指反光）","ex":{"en":"We could see the gleam of moonlight on the water.","cn":"我们看见水面上荡漾的月光。"},"pos":"noun"},{"en":"a small amount of something","cn":"少量；一丝；一线","ex":{"en":"a faint gleam of hope","cn":"微弱的一线希望"},"pos":"noun"},{"en":"an expression of a particular feeling or emotion that shows in somebody’s eyes","cn":"（感情在眼中的）表露，闪现","ex":{"en":"a gleam of triumph in her eyes","cn":"她眼里闪烁着胜利的光芒"},"pos":"noun"}]}},"glamour":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"魅力；吸引力；诱惑力","en":"Glamour is the quality of being more attractive, exciting, or interesting than ordinary people or things.","ex":{"en":"...the glamour of show biz.","cn":"娱乐界的诱惑"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feature or quality that makes people like, want, or feel interested in something","cn":""},{"en":"a quality that makes people like something or someone","cn":""},{"en":"a very attractive quality that makes you want something very much – often used about something that has a bad effect or influence","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Glamour is the quality of being fascinating, alluring, or charming If you've watched Marilyn Monroe on a movie screen, then you've witnessed glamour !"}]},"collocations":{"phrases":["QUANT. touch Several film stars were invited to add a touch of glamour to the occasion.","VERB + GLAMOUR have He had a glamour about him that she found very attractive. | lack Jumbo jets somehow lack the glamour of the transatlant","PHRASES a certain glamour"]},"media":{"uk":"media/ldoce/hwd/bre/3/glamor0205.mp3","us":"media/ldoce/hwd/ame/e/laadglamour.mp3"},"examples":[{"en":"Now that she's a flight attendant, foreign travel has lost its glamour for her.","cn":"她现在是空中乘务员了，去国外旅行对她已失去魅力。"},{"en":"hopeful young actors and actresses dazzled by the glamour of Hollywood","cn":"为好莱坞的魅力神魂颠倒时刻怀抱希望的年轻演员"}],"oxford":{"phon":"ˈɡlæmə(r)","pos":"noun","senses":[{"en":"the attractive and exciting quality that makes a person, a job or a place seem special, often because of wealth or status","cn":"吸引力，魅力，诱惑力（多因财富或地位所致）","ex":{"en":"hopeful young actors dazzled by the glamour of Hollywood","cn":"满怀希望的年轻演员为好莱坞的魅力神魂颠倒"}},{"en":"physical beauty that also suggests wealth or success","cn":"（暗示财富或成功的）迷人的美，魅力","ex":{"en":"Her long dark hair lent her a certain glamour.","cn":"乌黑长发赋予她某种魅力。"}},{"en":"a US women's magazine published by Condé Nast. It began in 1939 and covers fashion, beauty, health and news about famous people. It also has articles about other interests, such as business, politics, travel, food and relationships. Each year it holds the Glamour Woman of the Year Awards. There has been a British version of the magazine since 2001, and there are also versions in several other countries.","cn":"魅力：康泰纳仕（CondéNast）发行的美国女性杂志。它始于1939年，涵盖时尚，美容，健康和名人新闻。它还有关于其他兴趣的文章，例如商业，政治，旅行，饮食和人际关系。每年，它都会获得“年度魅力女人”奖。自2001年以来，该杂志已发行了英文版本，在其他几个国家也发行了该版本。","pos":""}]}},"glimmer":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发微光；隐约闪烁","en":"If something glimmers, it produces or reflects a faint, gentle, often unsteady light.","ex":{"en":"The moon glimmered faintly through the mists.","cn":"月亮透过薄雾洒下微光。"}},{"pos":"N-COUNT 可数名词","cn":"（常指闪烁的）微光","en":"A glimmer is a faint, gentle, often unsteady light.","ex":{"en":"In the east there is the slightest glimmer of light.","cn":"东方闪现出一丝微光。"}},{"pos":"N-COUNT 可数名词","cn":"一丝；少许","en":"A glimmer of something is a faint sign of it.","ex":{"en":"Despite an occasional glimmer of hope, this campaign has not produced any results","cn":"虽然偶尔会闪现一丝希望，但是这场宣传活动目前并无任何效果。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"making you feel more confident and hopeful","cn":""},{"en":"seeming likely to be good or successful","cn":""},{"en":"if something such as a new situation or discovery offers hope , it makes it possible for people to feel more hopeful that a bad situation will improve","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A glimmer is a tiny glint of light or the sliver of an idea. Either way, it's a sign of a lot more going on behind the scenes."}]},"collocations":{"phrases":["ADJ. faint, tiny In the east we could see the first faint glimmer of dawn. (figurative) The faint glimmer of an idea had crept into his mind","PREP. ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/7/glimmer_n0205.mp3","us":"media/ldoce/hwd/ame/2/glimmer1.mp3"},"examples":[{"en":"We could see a glimmer of light on the far shore.","cn":"我们可以看到对岸远处微微闪烁的灯光。"},{"en":"I caught the glimmer of a smile in his eyes.","cn":"我看到他眼里闪现出一丝笑意。"}],"oxford":{"phon":"ˈɡlɪmə(r)","pos":"noun","senses":[{"en":"a small unsteady light","cn":"微弱的闪光；闪烁的微光","ex":{"en":"We could see a glimmer of light on the far shore.","cn":"我们可以看到远处岸上微微闪烁的灯光。"}},{"en":"a small sign of something","cn":"微弱的迹象；一丝；一线","ex":{"en":"a glimmer of hope","cn":"一线希望"}},{"en":"to shine with a small unsteady light","cn":"隐约地闪烁；发出微弱的闪光","lab":"figurative","ex":{"en":"The candles glimmered in the corner.","cn":"烛光在角落里忽明忽暗地闪烁。"},"pos":"verb"}]}},"glitter":{"collins":{"senses":[{"pos":"VERB 动词","cn":"闪烁；闪亮","en":"If something glitters, light comes from or is reflected off different parts of it.","ex":{"en":"The bay glittered in the sunshine","cn":"海湾在阳光下闪闪发光。"}},{"pos":"VERB 动词","cn":"（激动、感兴趣等情感）闪现，流露","en":"If someone's eyes glitter, they are bright and express a particular emotion such as excitement or interest.","ex":{"en":"His eyes glittered with a tense amusement.","cn":"他眼里流露出一丝紧张和愉悦。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（粘在物体上作装饰用的）小发光物","en":"Glitter consists of tiny shining pieces of metal. It is glued to things for decoration.","ex":{"en":"Decorate the tunic with sequins or glitter.","cn":"用些圆形小金属片或发光小亮片装饰这件女式短上衣。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"外在的吸引力；魅力","en":"You can use glitter to refer to superficial attractiveness or to the excitement connected with something.","ex":{"en":"She was blinded by the glitter and the glamour of her own life.","cn":"她被自己的生活中表面上的光鲜与奢华所蒙蔽。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something sparkles, it shines with many small bright points when light is on it","cn":""},{"en":"to shine by reflecting the light – used especially about smooth clean surfaces, or about someone’s eyes or teeth","cn":""},{"en":"to shine with quick flashes of light","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A glitter is a sparkle or flash of light. To glitter is to gleam or shine, as if glistening with moisture."}]},"collocations":{"phrases":["ADV. brightly Crystal chandeliers glittered brightly above them.","PREP. in His metal buttons glittered in the sunlight. | with Trees and grass glittered with dew. 2 show emotion","ADV. coldly, dangerously, darkly, fiercely, strangely His deep-set eyes glittered coldly.","PREP. with Her eyes glittered with delight."]},"media":{"uk":"media/ldoce/hwd/bre/f/glitter_n0205.mp3","us":"media/ldoce/hwd/ame/7/glitter1.mp3"},"examples":[{"en":"His eyes glittered with greed.","cn":"他眼睛里闪现出贪婪的神色。"},{"en":"There was a triumphant glitter in his eyes.","cn":"他眼睛里闪烁着胜利的光辉。"}],"oxford":{"phon":"ˈɡlɪtə(r)","pos":"verb","senses":[{"en":"to shine brightly with little flashes of light, like a diamond","cn":"闪亮；闪耀；光彩夺目","g":"[intransitive]","ex":{"en":"The ceiling of the cathedral glittered with gold.","cn":"大教堂的天花板金光闪闪。"}},{"en":"to shine brightly with a particular emotion, usually a strong one","cn":"闪现（某种强烈情感）","g":"[intransitive]","ex":{"en":"His eyes glittered with greed.","cn":"他眼睛里闪现出贪婪的神色。"}},{"en":"bright light consisting of many little flashes","cn":"灿烂的光辉；闪烁；闪耀","g":"[uncountable]","ex":{"en":"the glitter of diamonds","cn":"钻石的光彩"},"pos":"noun"},{"en":"a bright expression in somebody’s eyes showing a particular emotion","cn":"（眼睛里某种感情的）闪现，流露","g":"[singular]","ex":{"en":"There was a triumphant glitter in his eyes.","cn":"他眼睛里闪烁着胜利的光辉。"},"pos":"noun"},{"en":"the attractive, exciting qualities that somebody/something, especially a rich and famous person or place, seems to have","cn":"吸引力；魅力；诱惑力","g":"[uncountable]","ex":{"en":"the superficial glitter of show business","cn":"演艺业表面上的光彩迷人"},"pos":"noun"},{"en":"very small shiny pieces of thin metal or paper that are stuck to things as a decoration","cn":"（装饰用的）小发光物","g":"[uncountable]","ex":{"en":"gold/silver glitter","cn":"金色的／银色的闪光装饰物"},"pos":"noun"}]}}});
